x=S[1];a='<li><b>受监管企业：</b>能耗下降，产出也下降，未发现显著的额外能效改善</li>';b='''<li><b>受监管企业：</b>能耗下降，产出也下降，未发现显著的额外能效改善。<p><b>能耗 E</b> 是能源使用总量；<b>能效 Y/E</b> 是每单位能源对应的产出，本文实证主要用产值衡量产出。</p><p class="caption">数值示例：产值从 100 万元降至 80 万元，能耗从 50 吨标准煤降至 40 吨标准煤。二者都下降 20%，能效仍为每吨标准煤对应 2 万元产值。论文中的“额外能效改善”指相对于对照组的改善。</p></li>''';assert a in x['body'];x['body']=x['body'].replace(a,b)
x=S[11]
x['body']='<h3>研究设计：同一企业跨年观察，两组企业相互比较</h3>'+table(['设计要素','本文的安排'],[['观察单位','企业—年份：同一家企业在多个年份形成重复观测'],['处理组 Treat=1','千家企业节能行动中的受监管企业'],['对照组 Treat=0','后来入选万家项目、基准期未受千家项目直接监管的企业；剔除主分析定义的关联企业'],['政策前后','2006 年及以前为政策前；2007 年及以后 Post=1，样本终点依数据库而异'],['结果变量','分别估计 ln(能耗)、ln(产出)、ln(能效)，对应三个结果方程']])+ '<h3>两次作差分别消去什么？</h3>'+para('同一企业的前后变化可扣除长期不变的企业差异；再减去对照组的同期变化，用于扣除共同的时间变化。下表以产出指数展示两次作差，数值仅作示意。')+x['body']+'<h3>因果解释依赖的条件</h3>'+para('平行趋势指：在没有千家项目的情形下，控制企业、行业和地区差异后，两组的平均结果沿相似趋势变化。若同期存在只影响处理组的其他冲击，或企业构成发生系统变化，β 仍可能混入这些影响。政策前的事件研究提供可观察的趋势证据。')
x['body']=x['body'].replace('若没有政策，受监管组也会增长到 110；实际为 90，与该反事实相差 20 个指数点。','在该示例的平行趋势与对照组不受溢出假设下，受监管组的无政策产出为 110；实际为 90，相差 20 个指数点。')
x=S[12];x['title']='DID 方程、固定效应与聚类标准误';x['sub']='回归系数描述相对效应，聚类标准误描述估计的不确定性'
x['body']=eq('zᵢⱼₖₜ = β(Treatᵢ × Postₜ) + αᵢ + ηⱼₜ + δₖₜ + X′ᵢₜγ + εᵢⱼₖₜ')+table(['组成部分','含义与作用'],[['zᵢⱼₖₜ','企业 i、二位行业 j、省份 k、年份 t 的结果；三个方程分别使用 ln E、ln Y 和 ln(Y/E)'],['Treatᵢ × Postₜ','仅受监管企业在 2007 年及以后取 1，其余企业—年份观测取 0'],['β','控制下列因素后，处理组政策前后变化与对照组变化的差额'],['αᵢ：企业固定效应','吸收长期不变的企业特征，如固定区位、长期管理差异'],['ηⱼₜ：行业×年固定效应','吸收某二位行业在某一年的共同冲击，如行业需求变化'],['δₖₜ：省份×年固定效应','吸收某省在某一年的共同冲击，如地区景气与共同政策变化'],['Xᵢₜ','第 (4) 列另加入国企状态、ROA、企业年龄与出口状态'],['εᵢⱼₖₜ','上述变量和固定效应未解释的企业—年份变化']])+para('Treat 对同一企业不随年份改变，其单独项被企业固定效应吸收；Post 的单独项被年度固定效应吸收。交互项随企业身份和年份共同变化，因而仍可估计。表中完整方程对应较充分的控制规格，各列逐步加入固定效应与企业特征。')+eq('能耗方程 β = −0.128：相对能耗变化约 −12.8%<br>精确比例变化 = 100 × [exp(−0.128)−1] ≈ −12.0%')+'<h3>标准误与聚类分别指什么？</h3>'+para('β̂ 是效应的点估计，标准误衡量该估计在重复抽样意义上的不确定性，并用于置信区间和显著性检验。同一企业的连续年份、或同一行业的不同企业，可能受到相关冲击；聚类标准误允许指定组内的误差相关，通常假定不同组之间近似独立。')+table(['做法','允许哪些误差相关','在本文中的用途'],[['企业层面聚类<br><code>cluster(firmid)</code>','同一家企业各年份之间可以相关；如未观察到的设备故障连续影响数年','Table 1 的直接效应、Table 2 的关联企业效应与相应事件研究'],['行业层面聚类<br><code>cluster(ind2)</code>','同一二位行业的不同企业及不同年份之间可以相关；如行业需求冲击影响多家企业并持续数年','Table 3 Panel A 的行业监管暴露回归']])+para('企业聚类以“企业的整段时间序列”为一组。行业聚类以“该行业全部企业的时间序列”为一组；同一行业内的企业即使数量很多，也未必提供同等数量的独立信息。行业回归中的监管暴露在行业层面变化，因此采用行业聚类来反映这一共同冲击结构。')+'<h3>固定效应与聚类标准误的分工</h3>'+para('固定效应进入回归方程，控制相应层级的共同均值变化；聚类则调整估计量的方差计算。在样本、权重和回归方程相同时，仅改变聚类层级通常保留同一个 β̂，但会改变标准误、置信区间与 p 值。较高层级聚类的标准误并不必然更大，其数值取决于误差相关结构；聚类数量较少时，常规推断的精度也会受限。')+para('本文的两种做法分别用于不同回归，并非同一回归中的“双向聚类”。聚类反映统计不确定性，政策识别仍依赖平行趋势和其他研究设计条件。')
